// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // admin is the deployer (this test contract); the caller must be admin
        vm.prank(address(this));
        c.setOwner(newOwner);
        // General rule: after setOwner(a) by the admin, owner() == a for every a.
        assertTrue(c.owner() == newOwner);
    }
}
